import{_ as e,c as a,a2 as p,o}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"第二百二十一章 如何除灭恐惧","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/221第二百二十一章 如何除灭恐惧.md","filePath":"meditation/巴利文大藏经/221第二百二十一章 如何除灭恐惧.md"}'),r={name:"meditation/巴利文大藏经/221第二百二十一章 如何除灭恐惧.md"};function _(n,t,i,s,d,c){return o(),a("div",null,t[0]||(t[0]=[p('<h1 id="第二百二十一章-如何除灭恐惧" tabindex="-1">第二百二十一章 如何除灭恐惧 <a class="header-anchor" href="#第二百二十一章-如何除灭恐惧" aria-label="Permalink to &quot;第二百二十一章 如何除灭恐惧&quot;">​</a></h1><p>完全读懂巴利文大藏经</p><p>相应部22相应7经/由于执取的战慄经(蕴相应/蕴篇/修多罗)</p><p>有个时候，佛陀住在舍卫城的祇树林给孤独园，有一天，佛陀对出家弟子们说：“比丘们（出家人）！如来现在要教导你们：由执着生起的忧愁、悲伤、苦闷、忧虑、绝望、恐惧是如何形成发生的？如何除灭由执着生起的忧愁、悲伤、苦闷、忧虑、绝望、恐惧？你们要认真的听，你们要仔细的思考，如来要开始说法了。”</p><p>出家弟子们回答：“世尊，我们会认真听您说法的，我们会仔细的思考的，恭请世尊您为我们说法。”</p><p>佛陀说：“比丘们！由执着生起的忧愁、悲伤、苦闷、忧虑、绝望、恐惧是如何形成发生的呢？那些没有受到圣者教导的世间人，由于他们没有听闻到圣者的教导，所以他们不知道圣者的正法，不会用圣者的方法去修行；那些没有受到善人教导的世间人，由于他们没有听闻到善人的教导，所以他们不知道善人的善法，不会去行善人的善法。这些世间人，他们会认为自己的物质身体就是我，会认为物质事物是我所拥有的；或者认为物质身体是我的一部分，或者认为我是物质身体的一部分；当他们的物质身体发生变化的时候，当他们的物质身体生病、衰老、临死的时候，当他们拥有的物质事物发生变化的时候，当他们失去拥有的物质事物，或者当他们拥有的物质事物衰败、灭亡、消失的时候，他们就会去分别、区别物质身体、物质事物的这些变化，他们的内心就会随着物质身体、物质事物的变化而生起忧愁、悲伤、苦闷、忧虑、绝望、恐惧，因为他们错认为自己的物质身体是可以永远保持健康，永远青春不老，永远不死的。他们错认为他们拥有的物质事物是可以永远拥有的。就是因为他们认为自己可以永远健康，永远年轻，永远不死，所以当他们的物质身体生病、衰老、临死的时候，他们就会产生忧愁、悲伤、苦闷、忧虑、绝望、恐惧。就是因为他们认为可以永远拥有物质事物，所以当他们失去自己拥有的物质事物，或者当他们拥有的物质事物衰败、灭亡、消失的时候，他们就会产生忧愁、悲伤、苦闷、忧虑、绝望、恐惧。就是因为他们贪爱、执着、挂念自己的物质身体，所以当他们的物质身体生病、衰老、临死的时候，他们就会产生烦恼和痛苦。就是因为他们贪爱、执着、挂念自己拥有的物质事物，所以当他们失去自己拥有的物质事物，或者当他们拥有的物质事物衰败、灭亡、消失的时候，他们就会产生烦恼和痛苦。</p><p>比丘们！同样的道理，那些没有受到圣者教导的世间人，由于他们没有听闻到圣者的教导，所以他们不知道圣者的正法，不会用圣者的方法去修行；那些没有受到善人教导的世间人，由于他们没有听闻到善人的教导，所以他们不知道善人的善法，不会去行善人的善法。这些世间人，他们会认为感受、念想、行为、认识、分别、判断就是我；或者认为感受、念想、行为、认识、分别、判断是我的一部分，或者认为我是感受、念想、行为、认识、分别、判断的一部分；当他们的感受、念想、行为、认识、分别、判断发生变化的时候，当他们的感受、念想、行为、认识、分别、判断让他们不满意、不开心、不快乐的时候，他们就会去分别、区别感受、念想、行为、认识、分别、判断的这些变化，他们的内心就会随着感受、念想、行为、认识、分别、判断的变化而生起忧愁、悲伤、苦闷、忧虑、绝望、恐惧，因为他们错认为自己的感受、念想、行为、认识、分别、判断是可以永远保持不变的。他们错认为让自己满意、开心、快乐的感受、念想、行为、认识、分别、判断是可以永远存在的。就是因为他们认为让自己满意、开心、快乐的感受、念想、行为、认识、分别、判断是可以永远存在，是可以永远保持不变的，所以当他们面对不满意、不开心、不快乐的感受、念想、行为、认识、分别、判断的时候，就会产生忧愁、悲伤、苦闷、忧虑、绝望、恐惧。就是因为他们贪爱、执着、挂念自己满意、开心、快乐的感受、念想、行为、认识、分别、判断。所以当他们的感受、念想、行为、认识、分别、判断不让他们满意、开心、快乐的时候，他们就会产生烦恼和痛苦。</p><p>比丘们！这就是由执着生起忧愁、悲伤、苦闷、忧虑、绝望、恐惧的过程。</p><p>比丘们！如何除灭由执着生起的忧愁、悲伤、苦闷、忧虑、绝望、恐惧呢？</p><p>比丘们！那些受到圣者教导的世间人，由于他们听闻到圣者的教导，所以他们知道圣者的正法，会用圣者的方法去修行；那些受到善人教导的世间人，由于他们听闻到善人的教导，所以他们知道善人的善法，会去行善人的善法。这些世间人，他们不会认为自己的物质身体就是我，不会认为物质事物是我所拥有的；或者不会认为物质身体是我的一部分，或者不会认为我是物质身体的一部分；当他们的物质身体发生变化的时候，当他们的物质身体生病、衰老、临死的时候，当他们拥有的物质事物发生变化的时候，当他们失去拥有的物质事物，或者当他们拥有的物质事物衰败、灭亡、消失的时候，他们就不会去分别、区别物质身体、物质事物的这些变化，他们的内心就不会随着物质身体、物质事物的变化而生起忧愁、悲伤、苦闷、忧虑、绝望、恐惧，因为他们不会错认为自己的物质身体是可以永远保持健康，永远青春不老，永远不死的。他们不会错认为他们拥有的物质事物是可以永远拥有的。就是因为他们不会认为自己可以永远健康，永远年轻，永远不死，所以当他们的物质身体生病、衰老、临死的时候，他们就不会产生忧愁、悲伤、苦闷、忧虑、绝望、恐惧。就是因为他们不会认为可以永远拥有物质事物，所以当他们失去自己拥有的物质事物，或者当他们拥有的物质事物衰败、灭亡、消失的时候，他们就不会产生忧愁、悲伤、苦闷、忧虑、绝望、恐惧。就是因为他们不会贪爱、执着、挂念自己的物质身体，所以当他们的物质身体生病、衰老、临死的时候，他们就不会产生烦恼和痛苦。就是因为他们不会贪爱、执着、挂念自己拥有的物质事物，所以当他们失去自己拥有的物质事物，或者当他们拥有的物质事物衰败、灭亡、消失的时候，他们就不会产生烦恼和痛苦。</p><p>比丘们！同样的道理，那些受到圣者教导的世间人，由于他们听闻到圣者的教导，所以他们知道圣者的正法，会用圣者的方法去修行；那些受到善人教导的世间人，由于他们听闻到善人的教导，所以他们知道善人的善法，会去行善人的善法。这些世间人，他们不会认为感受、念想、行为、认识、分别、判断就是我；或者不会认为感受、念想、行为、认识、分别、判断是我的一部分，或者不会认为我是感受、念想、行为、认识、分别、判断的一部分；当他们的感受、念想、行为、认识、分别、判断发生变化的时候，当他们的感受、念想、行为、认识、分别、判断让他们不满意、不开心、不快乐的时候，他们就不会去分别、区别感受、念想、行为、认识、分别、判断的这些变化，他们的内心就不会随着感受、念想、行为、认识、分别、判断的变化而生起忧愁、悲伤、苦闷、忧虑、绝望、恐惧，因为他们不会错认为自己的感受、念想、行为、认识、分别、判断是可以永远保持不变的。他们不会错认为让自己满意、开心、快乐的感受、念想、行为、认识、分别、判断是可以永远存在的。就是因为他们不会认为让自己满意、开心、快乐的感受、念想、行为、认识、分别、判断是可以永远存在，是可以永远保持不变的，所以当他们面对不满意、不开心、不快乐的感受、念想、行为、认识、分别、判断的时候，就不会产生忧愁、悲伤、苦闷、忧虑、绝望、恐惧。就是因为他们不会贪爱、执着、挂念自己满意、开心、快乐的感受、念想、行为、认识、分别、判断。所以当他们的感受、念想、行为、认识、分别、判断不让他们满意、开心、快乐的时候，他们就不会产生烦恼和痛苦。</p><p>比丘们！这就是除灭由执着生起忧愁、悲伤、苦闷、忧虑、绝望、恐惧的过程。”</p><p>佛陀说法后，听法的出家弟子们都再次的顶礼佛陀，随喜赞叹佛陀说法的无量功德，他们都按着佛陀所说的法去修行。</p>',13)]))}const f=e(r,[["render",_]]);export{m as __pageData,f as default};
